    "question": "Q414. [Advanced NEET Challenge] Hinsberg's reagent (Benzenesulfonyl chloride, $\\text{C}_6\\text{H}_5\\text{SO}_2\\text{Cl}$) reacts with a primary amine to form a product that is:",
