      "given": "$C_6H_5N_2^+ Cl^-$ treated with $H_3PO_2 + H_2O$.",
      "formula": "$C_6H_5N_2^+ Cl^- + H_3PO_2 + H_2O \\xrightarrow{Cu^+} C_6H_6 + N_2 + H_3PO_3 + HCl$",
